def real_room_types(apps, schema_editor):
    RoomType = apps.get_model("dashboard", "RoomType")
    Room = apps.get_model("dashboard", "Room")
    RoomPackage = apps.get_model("dashboard", "RoomPackage")
    Season = apps.get_model("dashboard", "Season")
    BaseRate = apps.get_model("dashboard", "BaseRate")
    Event = apps.get_model("dashboard", "Event")
    seasons = {season.name: season for season in Season.objects.all()}
    for old_code, (code, name, factor, markup, guests, view, notes, euros) in ROOM_TYPES.items():
        room_type = RoomType.objects.filter(code=old_code).first() or RoomType.objects.filter(code=code).first()
        if room_type is None:
            continue
        room_type.code, room_type.name = code, name
        room_type.standard_cost_factor, room_type.target_markup = Decimal(factor), Decimal(markup)
        room_type.max_guests = guests
        room_type.base_capacity = min(room_type.base_capacity, guests)
        room_type.description = f"{notes} Kaynak: {SITE}."
        room_type.save()
        Room.objects.filter(room_type=room_type).update(view_type=view)
        for package in RoomPackage.objects.filter(room_type=room_type):
            package.name = f"{name} - {package.guest_count} kişi"
            package.active = package.guest_count <= guests      # kapasiteyi aşan paket kullanılmaz
            package.save(update_fields=["name", "active"])
        for season_name, euro in zip(SEASON_ORDER, euros):
            if season_name in seasons:
                BaseRate.objects.update_or_create(room_type=room_type, season=seasons[season_name], defaults={
                    "price": (EURO * euro).quantize(Decimal("0.01")),
                    "notes": f"{euro} € × {EURO} TL (ECB 13.10.2026). Varsayım: standart oda kışın 85 €, üst tipler kademeli.",
                })
    for name, kind, start, end, index, source, notes in PAST_EVENTS:
        Event.objects.get_or_create(name=name, start_date=start, defaults={
            "kind": kind, "end_date": end, "index": Decimal(index), "source": source, "notes": notes})


